mapper.select:
SELECT c.*, p.name AS project_name, u.nickname AS create_by_name
FROM pm_cost c
JOIN pm_project p ON p.id = c.project_id
LEFT JOIN sys_user u ON u.id = c.create_by

    c.project_id = #{projectId}
    AND c.cost_type = #{costType}
    AND c.cost_date >= #{beginDate}
    AND c.cost_date <= #{endDate}

ORDER BY c.cost_date DESC, c.id DESC
